// Builds the layered PixelLab tile pack (format 2, docs/TILEPACK-LAYERED.md) in assets/packs/pixellab/ from the
// art generated by pixellab-sample.mjs in test-output/pixellab/sample/ (no API call).
//
//   node tools/packs/build-pixellab.mjs
//
// Terrain: one layer per Wang transition set (tileset-<key>/NWNESWSE.png), the lower terrain made transparent
// with pixellab-mask.mjs, 16 tiles in one row indexed NW*8 + NE*4 + SW*2 + SE. Sprites: the places picked in
// pixellab-picks.json, and every creature found on disk (anim/<name>/1..N.png, else the still
// character-<name>-south.png); creatures not generated yet are left out (the renderer draws the classic tile).
// Re-runnable: the output directory is rebuilt from scratch.
import fs from "node:fs";
import path from "node:path";
import { PNG } from "pngjs";
import { transitionMasks } from "./pixellab-mask.mjs";

const SRC = path.resolve("test-output/pixellab/sample");
const OUT = path.resolve("assets/packs/pixellab");
const SIZE = 32;
const PICKS = [path.resolve("tools/packs/pixellab-picks.json"), path.join(SRC, "picks.json")].find((f) => fs.existsSync(f));
const picks = JSON.parse(fs.readFileSync(PICKS, "utf8"));

const read = (f) => PNG.sync.read(fs.readFileSync(f));
const write = (f, img) => { fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, PNG.sync.write(img)); };

/** Terrain layers, bottom to top: [name, transition set, member SHAPES ids, water (fill texture), clip]. */
const LAYERS = [
  ["sea", "deep", [1, 2, 3, 4, 5, 6, 7, 8], true],
  ["shallows", "shallows", [2], true],
  ["land", "coast", [3, 4, 5, 6, 7, 8]],
  ["swamp", "swamp", [3], false, "land"],
  ["scrub", "scrub", [5], false, "land"],
  ["hills", "hills", [7], false, "land"],
  ["forest", "forest", [6], false, "land"],
  ["mountains", "mountains", [8], false, "land"],
];

/** Sprite name -> SHAPES ids (docs/TILEPACK-LAYERED.md, last table). */
const IDS = { dungeon: [9], town: [10], castle: [11, 14], shrine: [30], avatar: [0x1f] };
const range = (a, n) => Array.from({ length: n }, (_, i) => a + i);
["mage", "bard", "fighter", "druid", "tinker", "paladin", "ranger", "shepherd"].forEach((n, i) => (IDS[n] = range(0x20 + 2 * i, 2)));
["guard", "merchant", "minstrel", "jester", "beggar", "child", "bull", "king"].forEach((n, i) => (IDS[n] = range(0x50 + 2 * i, 2)));
["nixie", "squid", "seaserpent", "seahorse", "whirlpool", "twister"].forEach((n, i) => (IDS[n] = range(0x84 + 2 * i, 2)));
["rat", "bat", "spider", "ghost", "slime", "troll", "gremlin", "mimic", "reaper", "insects", "gazer", "phantom", "orc",
  "skeleton", "rogue", "python", "ettin", "headless", "cyclops", "wisp", "evilmage", "liche", "lavalizard", "zorn", "daemon",
  "hydra", "dragon", "balron"].forEach((n, i) => (IDS[n] = range(0x90 + 4 * i, 4)));
const PLACES = ["town", "castle", "shrine", "dungeon"];

fs.rmSync(OUT, { recursive: true, force: true });

// --- terrain
const corners = (i) => [8, 4, 2, 1].map((b) => (i & b ? "1" : "0")).join("");
const layers = LAYERS.map(([name, set, members, water, clip]) => {
  const dir = path.join(SRC, `tileset-${set}`);
  const tiles = Object.fromEntries(range(0, 16).map((i) => [corners(i), read(path.join(dir, `${corners(i)}.png`))]));
  const mask = transitionMasks(tiles, SIZE);
  const strip = new PNG({ width: 16 * SIZE, height: SIZE });
  for (let i = 0; i < 16; i++) {
    const c = corners(i), t = tiles[c], m = mask(c);
    for (let p = 0; p < SIZE * SIZE; p++) {
      const d = ((p / SIZE | 0) * strip.width + i * SIZE + p % SIZE) * 4;
      t.data.copy(strip.data, d, p * 4, p * 4 + 3);
      strip.data[d + 3] = Math.round(m[p] * 255);
    }
  }
  write(path.join(OUT, "terrain", `${name}.png`), strip);
  const layer = { name, members, image: `terrain/${name}.png` };
  if (water) {
    fs.copyFileSync(path.join(dir, "1111.png"), path.join(OUT, "terrain", `${name}-fill.png`));
    Object.assign(layer, { fill: `terrain/${name}-fill.png`, scroll: [1, 0] });
  }
  if (clip) layer.clip = clip;
  return layer;
});
fs.copyFileSync(path.join(SRC, "tileset-deep", "0000.png"), path.join(OUT, "terrain", "base.png"));

// --- sprites
/** Frames side by side in one row. */
const strip = (frames) => {
  const { width: w, height: h } = frames[0], out = new PNG({ width: w * frames.length, height: h });
  frames.forEach((f, i) => { for (let y = 0; y < h; y++) f.data.copy(out.data, (y * out.width + i * w) * 4, y * w * 4, (y + 1) * w * 4); });
  return out;
};
/** Lowest row holding an opaque pixel (alpha >= 128) in any frame. */
const lowest = (frames) => {
  let b = -1;
  for (const f of frames) for (let y = f.height - 1; y > b; y--) {
    let hit = false;
    for (let x = 0; x < f.width && !hit; x++) hit = f.data[(y * f.width + x) * 4 + 3] >= 128;
    if (hit) { b = y; break; }
  }
  return b;
};
const sprites = [], missing = [];
for (const [name, ids] of Object.entries(IDS)) {
  let frames, dy = 0;
  if (PLACES.includes(name)) frames = [read(path.join(SRC, `sprite-${name}`, `${picks.sprites[name]}.png`))];
  else {
    const anim = path.join(SRC, "anim", name), still = path.join(SRC, `character-${name}-south.png`);
    const files = fs.existsSync(anim) ? fs.readdirSync(anim).filter((f) => /^\d+\.png$/.test(f)).sort((a, b) => parseInt(a) - parseInt(b)) : [];
    if (files.length) frames = files.map((f) => read(path.join(anim, f)));
    else if (fs.existsSync(still)) frames = [read(still)];
    else { missing.push(name); continue; }
    // creatures stand on the cell: the lowest opaque row of all frames ends 2 px above the cell bottom
    const b = lowest(frames);
    if (b >= 0) dy = frames[0].height - 1 - b - 2;
  }
  const { width: w, height: h } = frames[0];
  if (frames.some((f) => f.width !== w || f.height !== h)) throw new Error(`${name}: frames of different sizes`);
  write(path.join(OUT, "sprites", `${name}.png`), strip(frames));
  sprites.push({ name, ids, image: `sprites/${name}.png`, w, h, frames: frames.length, dy });
}

const pack = {
  name: "PixelLab",
  format: 2,
  tileSize: SIZE,
  fallback: "scale4x-derived",
  fps: 6,
  base: { image: "terrain/base.png", scroll: [1, 0] },
  terrainIds: range(0, 9),
  layers,
  underlay: { 9: 8, 10: 4, 11: 4, 14: 4, 30: 4 },
  groundOnly: { 13: 4, 15: 4 },
  sprites,
};
// number arrays on one line
const json = JSON.stringify(pack, null, 1).replace(/\[\s+([-\d,\s]+?)\s+\]/g, (m, a) => `[${a.split(/,\s*/).join(", ")}]`);
fs.writeFileSync(path.join(OUT, "pack.json"), json + "\n");
console.log(`pack: ${layers.length} layers, ${sprites.length} sprites (${sprites.map((s) => `${s.name}${s.frames > 1 ? `x${s.frames}` : ""} dy ${s.dy}`).join(", ")})`);
console.log(`missing: ${missing.join(", ") || "none"}`);
